import{_ as t,o as h,c,a2 as i}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Confidence Score","description":"","frontmatter":{},"headers":[],"relativePath":"learner/confidence.md","filePath":"learner/confidence.md"}'),o={name:"learner/confidence.md"};function e(a,n,g,r,u,s){return h(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="confidence-score" tabindex="-1">Confidence Score <a class="header-anchor" href="#confidence-score" aria-label="Permalink to &quot;Confidence Score&quot;">​</a></h1><p>Trên trang này# Confidence Score <a href="#confidence-score">​</a> Confidence không đo learner. Nó đo <strong>hệ thống</strong>: mức độ Nemo12 tin vào chính kết luận của mình về learner. Đây có lẽ là con số bị hiểu nhầm nhiều nhất, nên nói rõ ngay: confidence <strong>không phải</strong> mức tự tin của con bạn, và cũng <strong>không phải</strong> một cách nói khác của điểm số. Nó là câu trả lời cho <em>&quot;tôi đã thấy đủ để nói câu này chưa?&quot;</em></p><h2 id="vi-sao-can-mot-con-so-rieng-cho-viec-đo-​" tabindex="-1">Vì sao cần một con số riêng cho việc đó <a href="#vi-sao-can-mot-con-so-rieng-cho-viec-đo">​</a> <a class="header-anchor" href="#vi-sao-can-mot-con-so-rieng-cho-viec-đo-​" aria-label="Permalink to &quot;Vì sao cần một con số riêng cho việc đó [​](#vi-sao-can-mot-con-so-rieng-cho-viec-đo)&quot;">​</a></h2><p>Hãy so hai learner cùng có mức vững 0.85 ở một mảng kiến thức: Learner ALearner BSố bằng chứng214Loại bàicùng một dạng5 dạng khác nhauThời điểmđều trong một buổirải ra 6 tuầnKết quảnhất quánnhất quán<strong>Confidence<strong><strong>0.20</strong></strong>0.90</strong>Cùng một con số 0.85, hai tình huống hoàn toàn khác. Với A, câu đúng nên nói là <em>&quot;có vẻ con ổn, nhưng tôi chưa dám chắc&quot;</em>. Với B: <em>&quot;con vững phần này&quot;</em>. Một hệ thống chỉ lưu mỗi mastery sẽ đối xử với hai em này y hệt nhau — và đó là nguồn gốc của rất nhiều quyết định sai: bắt B học lại thứ đã chắc, hoặc để A đi tiếp trên một nền chưa được kiểm chứng.</p><h2 id="confidence-đuoc-tinh-tu-đau-​" tabindex="-1">Confidence được tính từ đâu <a href="#confidence-đuoc-tinh-tu-đau">​</a> <a class="header-anchor" href="#confidence-đuoc-tinh-tu-đau-​" aria-label="Permalink to &quot;Confidence được tính từ đâu [​](#confidence-đuoc-tinh-tu-đau)&quot;">​</a></h2><p>Bốn yếu tố, và cả bốn đều phải có: <strong>Số lượng bằng chứng.</strong> Nhiều quan sát thì chắc hơn ít quan sát. Nhưng lợi ích giảm dần rất nhanh — từ 2 lên 6 bằng chứng tạo khác biệt lớn; từ 20 lên 24 thì gần như không. <strong>Đa dạng nguồn.</strong> Bằng chứng từ bài luyện tập, bài đo, và nhận xét của thầy cô — cùng chỉ về một hướng — mạnh hơn nhiều so với 10 bằng chứng cùng một nguồn. <strong>Độ phủ.</strong> Mảng kiến thức này đã được thăm dò ở nhiều góc chưa, hay chỉ ở đúng một dạng bài quen thuộc? <strong>Tính nhất quán.</strong> Kết quả có ổn định không? Learner lúc đúng lúc sai thất thường sẽ có confidence thấp — và điều đó <strong>đúng</strong>: sự thất thường tự nó là thứ chưa hiểu được, không nên làm tròn thành trung bình. Con số ví dụ: mười câu đúng liên tiếp <em>cùng một dạng</em> cho mastery 0.85 nhưng confidence chỉ khoảng 0.48. Cũng mười câu đó nhưng trải qua nhiều dạng và nhiều buổi → confidence 0.88.</p><h2 id="confidence-thap-dan-toi-hanh-đong-khac-han-​" tabindex="-1">Confidence thấp dẫn tới hành động khác hẳn <a href="#confidence-thap-dan-toi-hanh-đong-khac-han">​</a> <a class="header-anchor" href="#confidence-thap-dan-toi-hanh-đong-khac-han-​" aria-label="Permalink to &quot;Confidence thấp dẫn tới hành động khác hẳn [​](#confidence-thap-dan-toi-hanh-đong-khac-han)&quot;">​</a></h2><p>Đây là chỗ con số này trở nên hữu ích chứ không chỉ là chi tiết kỹ thuật:</p><ul><li><strong>Mastery thấp, confidence cao</strong> → đã rõ là con còn hụt. Đi học phần đó.</li><li><strong>Mastery thấp, confidence thấp</strong> → <strong>chưa biết</strong>. Đo thêm 1–3 câu trước khi kết luận. Rất thường xuyên, hoá ra con vẫn ổn — và ta vừa tiết kiệm được một buổi học lại không cần thiết.</li><li><strong>Mastery cao, confidence thấp</strong> → có vẻ ổn nhưng chưa chắc. Đo xác nhận, đừng vội cho là xong.</li><li><strong>Mastery cao, confidence cao</strong> → đi tiếp. Ô thứ hai là chỗ Nemo12 tiết kiệm được nhiều thời gian nhất cho learner. Phản xạ thông thường khi thấy một chỉ số thấp là <em>bắt học lại</em>. Phản xạ đúng là <em>đo cho chắc trước đã</em>.</li></ul><h2 id="confidence-cung-mo-đi-theo-thoi-gian-​" tabindex="-1">Confidence cũng mờ đi theo thời gian <a href="#confidence-cung-mo-đi-theo-thoi-gian">​</a> <a class="header-anchor" href="#confidence-cung-mo-đi-theo-thoi-gian-​" aria-label="Permalink to &quot;Confidence cũng mờ đi theo thời gian [​](#confidence-cung-mo-đi-theo-thoi-gian)&quot;">​</a></h2><p>Một kết luận dựa trên bằng chứng ba tháng trước không đáng tin bằng kết luận dựa trên bằng chứng tuần trước — kể cả khi bằng chứng lúc đó rất mạnh. Trẻ con thay đổi. Lưu ý đây là chuyện khác với việc quên: confidence là <em>độ tin của ước lượng</em>, còn retention là <em>trạng thái trí nhớ hiện tại của learner</em>. Hai chiều đo độc lập. <a href="/decisions/retention">Xem retention →</a></p><h2 id="vi-sao-gia-đinh-nen-quan-tam-​" tabindex="-1">Vì sao gia đình nên quan tâm <a href="#vi-sao-gia-đinh-nen-quan-tam">​</a> <a class="header-anchor" href="#vi-sao-gia-đinh-nen-quan-tam-​" aria-label="Permalink to &quot;Vì sao gia đình nên quan tâm [​](#vi-sao-gia-đinh-nen-quan-tam)&quot;">​</a></h2><p>Vì nó cho bạn một câu hỏi mới, tốt hơn hẳn câu hỏi cũ. Thay vì <em>&quot;con được mấy điểm phần này?&quot;</em>, câu đáng hỏi là: <strong>&quot;cái này biết chắc chưa, hay mới chỉ là phỏng đoán?&quot;</strong> Một hệ thống dám nói &quot;tôi chưa biết&quot; đáng tin hơn nhiều một hệ thống lúc nào cũng có sẵn con số cho mọi ô. Trong giáo dục, sự tự tin giả là thứ tốn kém: nó dẫn tới quyết định lớn — chọn trường, chọn lớp, chọn lộ trình ôn thi — dựa trên dữ liệu mỏng mà không ai biết là nó mỏng. Cùng một kết luận, nhưng &quot;chắc chắn&quot; và &quot;phỏng đoán&quot; phải dẫn tới hai hành động khác nhau. Confidence là thứ giữ cho sự phân biệt đó không bị mất. <a href="/learner/mot-bai-test-khong-du">Vì sao một bài test không đủ →</a></p>',13)])])}const d=t(o,[["render",e]]);export{l as __pageData,d as default};
